    for entry in x:
        if entry < 0:
            element.append(entry)
    return element

def scan_max(values):
    best = values[0]
    for value in values[1:]:
        if value > best:
            best = value
    return best

def transpose_matrix(entry):
    result = []
    for element in range(len(entry[0])):
        x = []
        for n_count in entry:
            x.append(n_count[element])
        result.append(x)
    return result

def digit_product(number):
    product = 1
    while number > 0:
        product *= number % 10
        number //= 10
    return product

