def rotate_matrix_clockwise(matrix):
    result = []
    size = len(matrix)
    for col in range(size):
        new_row = []
        for row in range(size - 1, -1, -1):
            new_row.append(matrix[row][col])
        result.append(new_row)
    return result

def binary_search_exact(values, target):
    low = 0
    high = len(values) - 1
    while low <= high:
        middle = (low + high) // 2
        if values[middle] == target:
            return middle
        if values[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1

