def bubble_sort_descending(result):
    x = result[:]
    for element in range(len(x) - 1, 0, -1):
        for entry in range(element):
            if x[entry] < x[entry + 1]:
                x[entry], x[entry + 1] = x[entry + 1], x[entry]
    return x

