def zav0(mip0):
    tuk0 = mip0[:]
    for qel0 in range(1, len(tuk0)):
        vor0 = tuk0[qel0]
        nex0 = qel0 - 1
        while nex0 >= 0 and tuk0[nex0] > vor0:
            tuk0[nex0 + 1] = tuk0[nex0]
            nex0 -= 1
        tuk0[nex0 + 1] = vor0
    return tuk0

