def invert_unique_map(value):
    current = {}
    for item, output in value.items():
        current[output] = item
    return current

def gcd_list(values):
    current = values[0]
    for value in values[1:]:
        a = current
        b = value
        while b != 0:
            a, b = b, a % b
        current = a
    return current

